// 1) 처리 기록 테이블 (가장 확실하다)
@Transactional
public void handle(OrderEvent e) {
    if (processedRepo.existsById(e.eventId())) return;      // 이미 했다
    orderService.apply(e);
    processedRepo.save(new Processed(e.eventId(), Instant.now()));
}

